(()=>{"use strict";document.addEventListener("click",e=>{const q=e.target.closest(".cloz-product-category .faq-question");if(!q)return;const item=q.closest(".faq-item"),open=q.getAttribute("aria-expanded")==="true";item.closest(".faq-accordion").querySelectorAll(".faq-item").forEach(i=>{i.classList.remove("is-active");i.querySelector(".faq-question")?.setAttribute("aria-expanded","false")});if(!open){item.classList.add("is-active");q.setAttribute("aria-expanded","true")}})})();
